5	part of reporting;
6	
7	/// Tells crash backend that the error is from the Flutter CLI.
8	const String _kProductId = 'Flutter_Tools';
9	
10	/// Tells crash backend that this is a Dart error as opposed to, say, Java.
11	const String _kDartTypeId = 'DartError';
12	
13	/// Crash backend host.
14	const String _kCrashServerHost = 'clients2.google.com';
15	
16	/// Path to the crash servlet.
17	const String _kCrashEndpointPath = '/cr/report';
18	
19	/// The field corresponding to the multipart/form-data file attachment where
20	/// crash backend expects to find the Dart stack trace.
21	const String _kStackTraceFileField = 'DartError';
22	
23	/// The name of the file attached as [_kStackTraceFileField].
24	///
25	/// The precise value is not important. It is ignored by the crash back end, but
26	/// it must be supplied in the request.
27	const String _kStackTraceFilename = 'stacktrace_file';
28	
29	/// Sends crash reports to Google.
30	///
31	/// There are two ways to override the behavior of this class:
32	///
33	/// * Define a `FLUTTER_CRASH_SERVER_BASE_URL` environment variable that points
34	///   to a custom crash reporting server. This is useful if your development
35	///   environment is behind a firewall and unable to send crash reports to
36	///   Google, or when you wish to use your own server for collecting crash
37	///   reports from Flutter Tools.
38	/// * In tests call [initializeWith] and provide a mock implementation of
39	///   [http.Client].
40	class CrashReportSender {
41	  CrashReportSender._(this._client);
42	
43	  static CrashReportSender _instance;
44	
45	  static CrashReportSender get instance => _instance ?? CrashReportSender._(http.Client());
46	
47	  bool _crashReportSent = false;
48	
49	  /// Overrides the default [http.Client] with [client] for testing purposes.
50	  @visibleForTesting
51	  static void initializeWith(http.Client client) {
52	    _instance = CrashReportSender._(client);
53	  }
54	
55	  final http.Client _client;
56	  final Usage _usage = Usage.instance;
57	
58	  Uri get _baseUrl {
59	    final String overrideUrl = platform.environment['FLUTTER_CRASH_SERVER_BASE_URL'];
60	
61	    if (overrideUrl != null) {
62	      return Uri.parse(overrideUrl);
63	    }
64	    return Uri(
65	      scheme: 'https',
66	      host: _kCrashServerHost,
67	      port: 443,
68	      path: _kCrashEndpointPath,
69	    );
70	  }
71	
72	  /// Sends one crash report.
73	  ///
74	  /// The report is populated from data in [error] and [stackTrace].
75	  Future<void> sendReport({
76	    @required dynamic error,
77	    @required StackTrace stackTrace,
78	    @required String getFlutterVersion(),
79	    @required String command,
80	  }) async {
81	    // Only send one crash report per run.
82	    if (_crashReportSent) {
83	      return;
84	    }
85	    try {
86	      final String flutterVersion = getFlutterVersion();
87	
88	      // We don't need to report exceptions happening on user branches
89	      if (_usage.suppressAnalytics || RegExp(r'^\[user-branch\]\/').hasMatch(flutterVersion)) {
90	        return;
91	      }
92	
93	      printStatus('Sending crash report to Google.');
94	
95	      final Uri uri = _baseUrl.replace(
96	        queryParameters: <String, String>{
97	          'product': _kProductId,
98	          'version': flutterVersion,
99	        },
100	      );
101	
102	      final http.MultipartRequest req = http.MultipartRequest('POST', uri);
103	      req.fields['uuid'] = _usage.clientId;
104	      req.fields['product'] = _kProductId;
105	      req.fields['version'] = flutterVersion;
106	      req.fields['osName'] = platform.operatingSystem;
107	      req.fields['osVersion'] = os.name; // this actually includes version
108	      req.fields['type'] = _kDartTypeId;
109	      req.fields['error_runtime_type'] = '${error.runtimeType}';
110	      req.fields['error_message'] = '$error';
111	      req.fields['comments'] = command;
112	
113	      req.files.add(http.MultipartFile.fromString(
114	        _kStackTraceFileField,
115	        stackTrace.toString(),
116	        filename: _kStackTraceFilename,
117	      ));
118	
119	      final http.StreamedResponse resp = await _client.send(req);
120	
121	      if (resp.statusCode == 200) {
122	        final String reportId = await http.ByteStream(resp.stream)
123	            .bytesToString();
124	        printStatus('Crash report sent (report ID: $reportId)');
125	        _crashReportSent = true;
126	      } else {
127	        printError('Failed to send crash report. Server responded with HTTP status code ${resp.statusCode}');
128	      }
129	    } catch (sendError, sendStackTrace) {
130	      if (sendError is SocketException || sendError is HttpException) {
131	        printError('Failed to send crash report due to a network error: $sendError');
132	      } else {
133	        // If the sender itself crashes, just print. We did our best.
134	        printError('Crash report sender itself crashed: $sendError\n$sendStackTrace');
135	      }
136	    }
137	  }
138	}
