27	/// Runs the Flutter tool with support for the specified list of [commands].
28	Future<int> run(
29	  List<String> args,
30	  List<FlutterCommand> commands, {
31	  bool muteCommandLogging = false,
32	  bool verbose = false,
33	  bool verboseHelp = false,
34	  bool reportCrashes,
35	  String flutterVersion,
36	  Map<Type, Generator> overrides,
37	}) {
38	  reportCrashes ??= !isRunningOnBot;
39	
40	  if (muteCommandLogging) {
41	    // Remove the verbose option; for help and doctor, users don't need to see
42	    // verbose logs.
43	    args = List<String>.from(args);
44	    args.removeWhere((String option) => option == '-v' || option == '--verbose');
45	  }
46	
47	  final FlutterCommandRunner runner = FlutterCommandRunner(verboseHelp: verboseHelp);
48	  commands.forEach(runner.addCommand);
49	
50	  return runInContext<int>(() async {
51	    // Initialize the system locale.
52	    final String systemLocale = await intl_standalone.findSystemLocale();
53	    intl.Intl.defaultLocale = intl.Intl.verifiedLocale(
54	      systemLocale, intl.NumberFormat.localeExists,
55	      onFailure: (String _) => 'en_US',
56	    );
57	
58	    String getVersion() => flutterVersion ?? FlutterVersion.instance.getVersionString(redactUnknownBranches: true);
59	    Object firstError;
60	    StackTrace firstStackTrace;
61	    return await runZoned<Future<int>>(() async {
62	      try {
63	        await runner.run(args);
64	        return await _exit(0);
65	      } catch (error, stackTrace) {
66	        firstError = error;
67	        firstStackTrace = stackTrace;
68	        return await _handleToolError(
69	            error, stackTrace, verbose, args, reportCrashes, getVersion);
70	      }
71	    }, onError: (Object error, StackTrace stackTrace) async {
72	      // If sending a crash report throws an error into the zone, we don't want
73	      // to re-try sending the crash report with *that* error. Rather, we want
74	      // to send the original error that triggered the crash report.
75	      final Object e = firstError ?? error;
76	      final StackTrace s = firstStackTrace ?? stackTrace;
77	      await _handleToolError(e, s, verbose, args, reportCrashes, getVersion);
78	    });
79	  }, overrides: overrides);
80	}
81	
82	Future<int> _handleToolError(
83	  dynamic error,
84	  StackTrace stackTrace,
85	  bool verbose,
86	  List<String> args,
87	  bool reportCrashes,
88	  String getFlutterVersion(),
89	) async {
90	  if (error is UsageException) {
91	    printError('${error.message}\n');
92	    printError("Run 'flutter -h' (or 'flutter <command> -h') for available flutter commands and options.");
93	    // Argument error exit code.
94	    return _exit(64);
95	  } else if (error is ToolExit) {
96	    if (error.message != null) {
97	      printError(error.message);
98	    }
99	    if (verbose) {
100	      printError('\n$stackTrace\n');
101	    }
102	    return _exit(error.exitCode ?? 1);
103	  } else if (error is ProcessExit) {
104	    // We've caught an exit code.
105	    if (error.immediate) {
106	      exit(error.exitCode);
107	      return error.exitCode;
108	    } else {
109	      return _exit(error.exitCode);
110	    }
111	  } else {
112	    // We've crashed; emit a log report.
113	    stderr.writeln();
114	
115	    if (!reportCrashes) {
116	      // Print the stack trace on the bots - don't write a crash report.
117	      stderr.writeln('$error');
118	      stderr.writeln(stackTrace.toString());
119	      return _exit(1);
120	    }
121	
122	    // Report to both [Usage] and [CrashReportSender].
123	    flutterUsage.sendException(error);
124	    await CrashReportSender.instance.sendReport(
125	      error: error,
126	      stackTrace: stackTrace,
127	      getFlutterVersion: getFlutterVersion,
128	      command: args.join(' '),
129	    );
130	
131	    if (error is String) {
132	      stderr.writeln('Oops; flutter has exited unexpectedly: "$error".');
133	    } else {
134	      stderr.writeln('Oops; flutter has exited unexpectedly.');
135	    }
136	
137	    try {
138	      final File file = await _createLocalCrashReport(args, error, stackTrace);
139	      stderr.writeln(
140	        'Crash report written to ${file.path};\n'
141	            'please let us know at https://github.com/flutter/flutter/issues.',
142	      );
143	      return _exit(1);
144	    } catch (error) {
145	      stderr.writeln(
146	        'Unable to generate crash report due to secondary error: $error\n'
147	            'please let us know at https://github.com/flutter/flutter/issues.',
148	      );
149	      // Any exception throw here (including one thrown by `_exit()`) will
150	      // get caught by our zone's `onError` handler. In order to avoid an
151	      // infinite error loop, we throw an error that is recognized above
152	      // and will trigger an immediate exit.
153	      throw ProcessExit(1, immediate: true);
154	    }
155	  }
156	}
