+bool _genSnapshotRuns(String genSnapshotPath) {
+  const int kExpectedExitCode = 255;
+  try {
+    return processUtils.runSync(<String>[genSnapshotPath]).exitCode == kExpectedExitCode;
+  } catch (error) {
+    return false;
+  }
