+          if (name.startsWith('.$id')) {
+            final String version = name.substring(id.length + 1);
+            String installPath;
+            try {
+              installPath = fs.file(fs.path.join(dir.path, 'system', '.home')).readAsStringSync();
+            } catch (e) {
