+    if (devices.isEmpty) {
+      return ValidationResult(ValidationType.notAvailable, messages);
+    } else {
+      return ValidationResult(ValidationType.installed, messages, statusInfo: userMessages.devicesAvailable(devices.length));
+    }
+  }
