+const String _kShortURL = 'https://www.example.com/short';
+
+void main() {
+  group('GitHub template creator', () {
+
+    testUsingContext('similar issues URL', () async {
+      final GitHubTemplateCreator creator = GitHubTemplateCreator();
+      expect(
