+      expect(
+        await creator.toolCrashIssueTemplateGitHubURL(command, errorString, exception, stackTrace, doctorText),
+        _kShortURL
+      );
+    }, overrides: <Type, Generator>{
+      HttpClientFactory: () => () => SuccessShortenURLFakeHttpClient(),
+    });
